%% EXP2 presentation figures. All plots generated by MATLAB R2022b.
% Run with make_exp2_presentation_figures(workspaceRoot).
% Raw temperatures are never overwritten. Profiles use reported baseline
% channel offsets and an explicitly marked +5 C aluminum Ch1 sensitivity scenario.
% NX node CSVs are the existing Take2 exports: verified face maxima against
% the individual 2026-10-09 Take2 reports (51.2/71.2/72.2/149.2/62.5 C).
% NX curves are plots of exported results, NOT NX viewport screenshots.
% End-window values are called final-window means, not steady temperatures.
function make_exp2_presentation_figures(workspaceRoot)
here=fileparts(mfilename('fullpath'));
if nargin<1, workspaceRoot=fileparts(fileparts(fileparts(fileparts(fileparts(fileparts(mfilename('fullpath'))))))); end
runRoot=fullfile(workspaceRoot,'Lab Data','EXP2','Runs');
offset=[0.02 1.41 -0.57 -0.86];
names={'Copper','Aluminum','Brass','Stainless','Copper tube'};
keys={'Copper','Aluminum','Brass','Stainless','CuTube'};
files={'R1/Copper.txt','R7/Aluminum2.txt','R6/Bronze2.txt','R4/Steel.txt','R5/Tube2.txt'};
x={[4.25 6.75 9.25 11.75],[2.5 3.5 4.5 5.5],[2.5 3.5 4.5 5.5],[3 4.5 6 7.5],[3.5 5.5 7.5 9.5]};
L=[11.75 12 12 11.75 11.99]; D=[.195 .1995 .201 .201 .3142]; Di=[0 0 0 0 .2358];
k=[387 155 116 17 387]; Ta=[26.14 27.16 27.27 24.23 26.82];
hNX=[10.49 18.74 25 25 18.86]; Q=[.769 1.337 1.372 1.472 2.186];
reportRMS=[.54 .73 2.11 .42 .30];
set(groot,'defaultAxesFontSize',24,'defaultTextFontSize',24,'defaultAxesFontName','Arial');
set(groot,'defaultFigureColor','w');
colors=[.00 .32 .62;.93 .40 .12;.17 .57 .40;.52 .27 .65];
result=struct([]);
for i=1:5
    v=sscanf(strrep(fileread(fullfile(runRoot,files{i})),',',' '),'%f');
    if i==1, T=reshape(v,4,[])'; t=(0:size(T,1)-1)'*5.06;
    else, M=reshape(v,5,[])'; t=M(:,1)-M(1,1); T=M(:,2:5); end
    w=t>=t(end)-180; rawMean=mean(T(w,:),1); corrected=rawMean-offset;
    slope=zeros(1,4); for c=1:4, pp=polyfit(t(w)/60,T(w,c),1); slope(c)=pp(1); end
    result(i).rod=names{i}; result(i).duration_min=t(end)/60;
    result(i).raw_mean=rawMean; result(i).corrected_mean=corrected; result(i).slope=slope;
    result(i).max_slope=max(abs(slope)); result(i).end_stable=all(abs(slope)<.1);
    result(i).nx_h=hNX(i); result(i).nx_Q=Q(i); result(i).report_RMS=reportRMS(i);
    f=figure('Visible','off','Position',[30 30 1100 600]); ax=axes(f); hold(ax,'on');
    for c=1:4, plot(t/60,T(:,c),'Color',colors(c,:),'LineWidth',2.1); end
    grid on; xlabel('Elapsed recording time (min)'); ylabel('Raw temperature (°C)');
    xlim([0 t(end)/60]); yl=ylim;
    patch([t(find(w,1))/60 t(end)/60 t(end)/60 t(find(w,1))/60],[yl(1) yl(1) yl(2) yl(2)],...
        [.7 .7 .7],'FaceAlpha',.12,'EdgeColor','none','HandleVisibility','off');
    title([names{i} ' | ' strtok(files{i},'/') ' raw transient'],'FontWeight','bold','FontSize',24);
    lg=legend('Ch1','Ch2','Ch3','Ch4','FontSize',20);
    lg.Units='normalized'; lg.Position=[.16 .62 .14 .21];
    text(.015,.97,sprintf('Final 3 min: max |dT/dt| = %.2f °C/min',max(abs(slope))),...
        'Units','normalized','VerticalAlignment','top','BackgroundColor','w','FontSize',18);
    exportgraphics(f,fullfile(here,['transient_' keys{i} '.png']),'Resolution',160); close(f);

    nd=readmatrix(fullfile(here,'data',['NX_' keys{i} '_nodes.csv']));
    edges=0:.1:max(nd(:,3))+.1; xn=[]; tn=[];
    for b=1:numel(edges)-1
        s=nd(:,3)>=edges(b)&nd(:,3)<edges(b+1);
        if any(s), xn(end+1)=mean(nd(s,3)); tn(end+1)=mean(nd(s,4)); end
    end
    xp=x{i}; yp=corrected; use=true(1,4); if i==1, use(4)=false; end
    if i==2, yp(1)=yp(1)+5; end
    % Fit the analytical insulated-tip fin solution to trusted final-window
    % data only. This is descriptive calibration, not validation or k recovery.
    xm=xp*.0254; lm=L(i)*.0254;
    obj=@(q) sum((Ta(i)+q(1)*cosh(abs(q(2))*(lm-xm(use)))/cosh(abs(q(2))*(lm-xm(1)))-yp(use)).^2);
    q=fminsearch(obj,[yp(1)-Ta(i),20],optimset('Display','off','MaxFunEvals',5000));
    xx=linspace(xp(1),L(i),300); analytical=Ta(i)+q(1)*cosh(abs(q(2))*(lm-xx*.0254))/cosh(abs(q(2))*(lm-xm(1)));
    result(i).profile_mean=yp;
    A=pi/4*((D(i)*.0254)^2-(Di(i)*.0254)^2); perimeter=pi*D(i)*.0254;
    result(i).h_over_k_fit=q(2)^2*A/perimeter;
    result(i).h_analytical=result(i).h_over_k_fit*k(i);
    dx=mean(diff(xm)); m2=(yp(1)+yp(3)-2*yp(2))/(dx^2*(yp(2)-Ta(i)));
    result(i).h_three_point=m2*A/perimeter*k(i);
    f=figure('Visible','off','Position',[30 30 1100 600]); hold on;
    plot(xn,tn,'Color',[.00 .32 .62],'LineWidth',2.6);
    plot(xx,analytical,'--','Color',[.93 .40 .12],'LineWidth',2.4);
    plot(xp(use),yp(use),'ko','MarkerFaceColor','k','MarkerSize',9);
    labels={'Take2 NX (data-fitted)','Analytical fin (data-fitted)','Adjusted final-window mean'};
    if i==1
        plot(xp(4),yp(4),'kx','LineWidth',2.5,'MarkerSize',13); labels{end+1}='Cu Ch4 excluded';
    elseif i==2
        plot(xp(1),corrected(1),'ks','MarkerSize',10,'LineWidth',2); labels{end+1}='Ch1 before assumed +5°C';
    elseif i==3
        plot([4.2 6.8],[35.88 30.94],'s','Color',[.52 .27 .65],'MarkerFaceColor',[.52 .27 .65],'MarkerSize',8);
        labels{end+1}='R3 adjusted transient points';
    end
    yline(Ta(i),':','Color',[.35 .35 .35],'LineWidth',1.7,'HandleVisibility','off');
    grid on; xlabel('Distance from heated face (in)'); ylabel('Temperature (°C)');
    xlim([max(0,min(xp)-.8) L(i)]); ylim([Ta(i)-2 max(yp)+5]);
    title([names{i} ' | final-window profile vs models'],'FontWeight','bold','FontSize',24);
    legend(labels,'Location','northeast','FontSize',20);
    exportgraphics(f,fullfile(here,['profile_' keys{i} '.png']),'Resolution',160); close(f);
end
f=figure('Visible','off','Position',[30 30 1100 600]);
bar(reportRMS,'FaceColor',[.00 .32 .62]); grid on; xticklabels(names);
ylabel('Reported NX fit RMS (°C)'); title('Take2 NX agreement at fitted sensors','FontSize',24);
for i=1:5, text(i,reportRMS(i)+.07,sprintf('%.2f',reportRMS(i)),'HorizontalAlignment','center'); end
ylim([0 2.6]);
exportgraphics(f,fullfile(here,'comparison_NX_RMS.png'),'Resolution',160); close(f);
fid=fopen(fullfile(here,'review_numbers.csv'),'w');
fprintf(fid,'Rod,duration_min,raw1,raw2,raw3,raw4,profile1,profile2,profile3,profile4,slope1,slope2,slope3,slope4,max_abs_slope,end_stable,hNX,Q_NX,report_RMS,hk_fit,h_analytical,h_three_point\n');
for i=1:5
    r=result(i);fprintf(fid,'%s',r.rod);
    vals=[r.duration_min r.raw_mean r.profile_mean r.slope r.max_slope r.end_stable r.nx_h r.nx_Q r.report_RMS r.h_over_k_fit r.h_analytical r.h_three_point];
    fprintf(fid,',%.6g',vals);fprintf(fid,'\n');
end
fclose(fid); save(fullfile(here,'review_numbers.mat'),'result');
type(fullfile(here,'review_numbers.csv'));
end
